app.use(async (c, next) => {
  c.header('Set-Cookie', 'mw=hello; Path=/', { append: true })
  await next()
})
app.get('/', () => {
  const res = new Response('ok')
  res.headers.append('set-cookie', 'handler=world; Path=/')
  return res
})

