input.newString:
set res(_res: Response | undefined) {
  // Headers set by `c.header()` may still be staged in `#preparedHeaders`
  // until something reads `c.res`, so fall back to them when `#res` is absent.
  const headers = this.#res?.headers ?? this.#preparedHeaders
  if (headers && _res) {
    _res = createResponseInstance(_res.body, _res)

    // `Set-Cookie` is the only header that can legitimately appear more than
    // once. Merge both sides instead of replacing the new response's cookies.
    const contextCookies = headers.getSetCookie()
    const responseCookies = _res.headers.getSetCookie()

    for (const [k, v] of headers.entries()) {
      if (k !== 'content-type' && k !== 'set-cookie') {
        _res.headers.set(k, v)
      }
    }

    if (contextCookies.length > 0) {
      _res.headers.delete('set-cookie')
      for (const cookie of contextCookies) {
        _res.headers.append('set-cookie', cookie)
      }
      for (const cookie of responseCookies) {
        if (!contextCookies.includes(cookie)) {
          _res.headers.append('set-cookie', cookie)
        }
      }
    }
  } else if (!_res) {
    // Discarding the response also discards headers that were never applied.
    this.#preparedHeaders = undefined
  }
  this.#res = _res
  this.finalized = true
}

